import time
from Pytrich.Heuristics.heuristic import Heuristic
from Pytrich.Search.htn_node import HTNNode
from Pytrich.model import Model

# This domain-dependent heuristic was generated by an LLM.
# It is designed for the Depot domain in HDDL.
class DepotGemini25ProHeuristic2(Heuristic):
    """
    A domain-dependent heuristic for the Depot domain.

    This heuristic estimates the cost of a plan by analyzing the methods used for task decomposition.
    It assigns penalties to methods based on the complexity and resource-intensiveness of their subtasks.
    The primary cost drivers in the Depot domain are:
    1. Driving trucks between locations ('Drive' action).
    2. Clearing stacks of crates to access a needed crate ('do_clear' task).

    The heuristic precomputes a score for each method in the domain based on the presence of these
    costly subtasks. Methods involving driving or complex clearing operations receive a higher penalty,
    guiding the planner to prefer more direct, local actions when possible.

    The penalties are kept small to ensure the heuristic is admissible (i.e., it never overestimates
    the true cost to reach the goal), which is crucial for optimal planning algorithms like A*.
    """
    def __init__(self, drive_penalty=0.4, clear_penalty=0.3, transport_penalty=0.2, base_op_penalty=0.1, name="depot_gemini25pro_heuristic_2"):
        super().__init__(name=name)
        # Penalty for methods involving driving a truck between locations.
        self.drive_penalty = drive_penalty
        # Penalty for methods that need to clear a surface, which can be a recursive and costly operation.
        self.clear_penalty = clear_penalty
        # Penalty for setup tasks for transportation like getting a truck or loading/unloading.
        self.transport_penalty = transport_penalty
        # Penalty for basic robotic operations like lifting or dropping a crate.
        self.base_op_penalty = base_op_penalty

        self.method_scores = {}
        self.preprocessing_time = 0

    def initialize(self, model: Model, initial_node: HTNNode):
        """
        Initializes the heuristic by pre-computing scores for all methods in the domain.
        """
        start_time = time.time()
        self.model = model
        self._precompute_method_info()
        self.preprocessing_time = time.time() - start_time

        h_value = self._calculate_node_heuristic(initial_node)
        return super().initialize(model, h_value)

    def _precompute_method_info(self):
        """
        Analyzes all decomposition methods in the domain model and assigns a heuristic score to each.
        The score reflects the estimated cost of the method's subtasks.
        This is done once at the beginning of the search.
        """
        self.method_scores = {}
        if not self.model or not hasattr(self.model, 'decompositions'):
            return

        for method in self.model.decompositions:
            method_name = method.name
            score = 0.0

            if not hasattr(method, 'task_network'):
                self.method_scores[method_name] = score
                continue

            for subtask in method.task_network:
                subtask_name = subtask.name.lower()

                # Penalize based on the type of subtask
                if 'drive' in subtask_name:
                    score += self.drive_penalty
                elif 'do_clear' in subtask_name:
                    score += self.clear_penalty
                elif 'do_load_truck' in subtask_name or \
                     'do_unload_truck' in subtask_name or \
                     'do_get_truck' in subtask_name:
                    score += self.transport_penalty
                elif 'lift' in subtask_name or \
                     'drop' in subtask_name or \
                     'load' in subtask_name or \
                     'unload' in subtask_name or \
                     'do_lift_crate' in subtask_name:
                    score += self.base_op_penalty
            
            self.method_scores[method_name] = score

    def _calculate_node_heuristic(self, node: HTNNode) -> float:
        """
        Calculates the heuristic value for a given search node.
        The value is based on the method used to create this node.
        """
        if not hasattr(node, 'method') or not node.method:
            # Node is likely a primitive action, no decomposition cost.
            return 0.0

        return self._score_method(node.method)

    def _score_method(self, method) -> float:
        """
        Retrieves the precomputed heuristic score for a given method.
        Returns a default low score if the method is not found.
        """
        method_name = method.name if hasattr(method, 'name') else str(method)
        return self.method_scores.get(method_name, 0.1) # Default score for unknown methods

    def __call__(self, parent_node: HTNNode, node: HTNNode) -> float:
        """
        The main heuristic evaluation function called by the planner.
        """
        h_value = self._calculate_node_heuristic(node)
        # Ensure heuristic remains admissible and provides a consistent signal
        h_value = min(h_value, 5.0) 
        super().update_info(h_value)
        return h_value

    def __repr__(self):
        return f"{self.__class__.__name__}(drive={self.drive_penalty}, clear={self.clear_penalty})"

    def __str__(self):
        return f"{self.__class__.__name__} with penalties: Drive={self.drive_penalty}, Clear={self.clear_penalty}, Transport={self.transport_penalty}"

    def __output__(self):
        return (
            f"{self.name} Heuristic Info:\n"
            f"\tMethods Analyzed: {len(self.method_scores)}\n"
            f"\tDrive Penalty: {self.drive_penalty}\n"
            f"\tClear Penalty: {self.clear_penalty}\n"
            f"\tTransport Penalty: {self.transport_penalty}\n"
            f"\tBase Operation Penalty: {self.base_op_penalty}\n"
            f"\tPreprocessing Time: {self.preprocessing_time:.4f} s\n"
        )
